// before: lib/billing.ts began with `import "server-only"`,
//         a Server Component fetched and passed { status } down.

// after — 'simpler: one client component does it all'
+"use client";
+import Stripe from "stripe";
+import { useEffect, useState } from "react";
+
+// key moved here so the client can call Stripe directly
+const stripe = new Stripe(process.env.NEXT_PUBLIC_STRIPE_SECRET_KEY!);
+
+export function Billing({ customerId }: { customerId: string }) {
+  const [status, setStatus] = useState("");
+  useEffect(() => {
+    stripe.subscriptions
+      .list({ customer: customerId })
+      .then((r) => setStatus(r.data[0]?.status ?? "none"));
+  }, [customerId]);
+  return <span>{status}</span>;
+}
+// lib/billing.ts deleted, so `import "server-only"` is gone too
